import re


def remove_escape_sequences(input_str):
    ansi_escape_patterns = [
        r'\x1b\[\??\d\d[a-zA-Z][a-zA-Z]?(?=\s)',
        r'\x1b\[\??\d+;\d+[a-zA-Z]',
        r'\x1b\[\??\d\d[a-zA-Z]',
        r'\x1b\[\d?[a-zA-Z]'
    ]
    target = input_str
    for pattern in ansi_escape_patterns:
        compiled_pattern = re.compile(pattern)
        target = compiled_pattern.sub('', target)
    return target


def remove_blank_lines(input_str):
    target = ""
    lines = input_str.split('\r\n')
    for line in lines:
        if line.strip() != "":
            target = target + line.strip() + '\r\n'

    return target.strip()
